import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.DSoq407f.js";const u=JSON.parse('{"title":"事件类型","description":"","frontmatter":{},"headers":[],"relativePath":"xubp/events.md","filePath":"xubp/events.md","lastUpdated":1782304957000}'),c={name:"xubp/events.md"};function r(s,t,i,l,n,h){return e(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="事件类型" tabindex="-1">事件类型 <a class="header-anchor" href="#事件类型" aria-label="Permalink to &quot;事件类型&quot;">​</a></h1><blockquote><p><strong>你会学到</strong>：XUBP 定义了哪些事件类型、它们如何映射到各平台、插件如何订阅。</p></blockquote><h2 id="事件类型一览" tabindex="-1">事件类型一览 <a class="header-anchor" href="#事件类型一览" aria-label="Permalink to &quot;事件类型一览&quot;">​</a></h2><p>XUBP 用<strong>点分命名法</strong>（<code>类别.子类型</code>）定义了 17 种通用事件类型。所有适配器都必须把平台原始事件映射成下表中的类型。</p><h3 id="消息类-message" tabindex="-1">消息类（message.*） <a class="header-anchor" href="#消息类-message" aria-label="Permalink to &quot;消息类（message.*）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>事件类型</th><th>说明</th><th>场景</th></tr></thead><tbody><tr><td><code>message.group</code></td><td>群聊消息（需要 @机器人）</td><td>群里 @你的机器人发的消息</td></tr><tr><td><code>message.group_full</code></td><td>群全量消息（无需 @）</td><td>群里的所有消息（需平台支持 + 开启）</td></tr><tr><td><code>message.private</code></td><td>私聊消息</td><td>用户单独发给机器人的消息</td></tr><tr><td><code>message.guild</code></td><td>频道消息</td><td>频道里的消息</td></tr><tr><td><code>message.guild_at</code></td><td>频道 @ 消息</td><td>频道里 @机器人的消息</td></tr><tr><td><code>message.guild_dm</code></td><td>频道私信</td><td>频道里的私信</td></tr></tbody></table><h3 id="机器人状态类-bot" tabindex="-1">机器人状态类（bot.*） <a class="header-anchor" href="#机器人状态类-bot" aria-label="Permalink to &quot;机器人状态类（bot.*）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>事件类型</th><th>说明</th></tr></thead><tbody><tr><td><code>bot.group_join</code></td><td>机器人被添加到群</td></tr><tr><td><code>bot.group_leave</code></td><td>机器人被移出群</td></tr><tr><td><code>bot.friend_add</code></td><td>机器人被添加为好友</td></tr><tr><td><code>bot.friend_remove</code></td><td>机器人被删除好友</td></tr><tr><td><code>bot.group_reject</code></td><td>群拒绝了机器人</td></tr><tr><td><code>bot.group_receive</code></td><td>群恢复了机器人</td></tr></tbody></table><h3 id="交互-表态-审核类" tabindex="-1">交互 / 表态 / 审核类 <a class="header-anchor" href="#交互-表态-审核类" aria-label="Permalink to &quot;交互 / 表态 / 审核类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>事件类型</th><th>说明</th></tr></thead><tbody><tr><td><code>interaction</code></td><td>交互事件（按钮回调等）</td></tr><tr><td><code>reaction.add</code></td><td>表情表态添加</td></tr><tr><td><code>reaction.remove</code></td><td>表情表态删除</td></tr><tr><td><code>audit.pass</code></td><td>消息审核通过</td></tr><tr><td><code>audit.reject</code></td><td>消息审核拒绝</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">关于全量消息</p><p><code>message.group</code> 是常规群消息（要 @机器人才触发）；<code>message.group_full</code> 是群里<strong>所有</strong>消息（无需 @）。 用户可在机器人的「适配器设置」里开启「全量消息当作普通群消息处理」，开启后 <code>group_full</code> 会自动转成 <code>group</code>，所有订阅 <code>message.group</code> 的插件都能收到。</p></div><h2 id="跨平台事件映射" tabindex="-1">跨平台事件映射 <a class="header-anchor" href="#跨平台事件映射" aria-label="Permalink to &quot;跨平台事件映射&quot;">​</a></h2><p>同一个 XUBP 事件类型，在不同平台上对应不同的原始事件。<strong>插件无需关心原始事件名</strong>，只需订阅通用类型即可。</p><table tabindex="0"><thead><tr><th>XUBP 通用类型</th><th>QQ 官方</th><th>Discord</th><th>Telegram</th><th>OneBot v11</th></tr></thead><tbody><tr><td><code>message.group</code></td><td><code>GROUP_AT_MESSAGE_CREATE</code></td><td>—</td><td>—</td><td><code>message.group</code></td></tr><tr><td><code>message.group_full</code></td><td><code>GROUP_MESSAGE_CREATE</code></td><td><code>MESSAGE_CREATE</code></td><td>—</td><td><code>message.group</code></td></tr><tr><td><code>message.private</code></td><td><code>C2C_MESSAGE_CREATE</code></td><td>应用私信</td><td>私聊 <code>message</code></td><td><code>message.private</code></td></tr><tr><td><code>message.guild</code></td><td><code>MESSAGE_CREATE</code></td><td>Guild 消息</td><td>—</td><td>—</td></tr><tr><td><code>bot.group_join</code></td><td><code>GROUP_ADD_ROBOT</code></td><td>—</td><td><code>my_chat_member</code></td><td><code>notice.group_increase</code></td></tr><tr><td><code>bot.group_leave</code></td><td><code>GROUP_DEL_ROBOT</code></td><td>—</td><td><code>my_chat_member</code></td><td><code>notice.group_decrease</code></td></tr><tr><td><code>bot.friend_add</code></td><td><code>FRIEND_ADD</code></td><td>—</td><td>—</td><td><code>notice.friend_add</code></td></tr><tr><td><code>interaction</code></td><td><code>INTERACTION_CREATE</code></td><td><code>INTERACTION_CREATE</code></td><td><code>callback_query</code></td><td>—</td></tr><tr><td><code>reaction.add</code></td><td><code>MESSAGE_REACTION_ADD</code></td><td><code>MESSAGE_REACTION_ADD</code></td><td>—</td><td>—</td></tr></tbody></table><details class="details custom-block"><summary>完整映射表</summary><p>上表只列了高频类型。完整映射见各平台适配器实现。&quot;—&quot; 表示该平台暂无对应的原生事件，适配器可在未来版本中通过组合事件或轮询实现。</p></details><blockquote><p>如果插件确实需要针对特定平台做特殊处理，可以从 <code>event[&quot;platform_event_type&quot;]</code> 读取平台原始事件类型。</p></blockquote><h2 id="插件如何订阅事件" tabindex="-1">插件如何订阅事件 <a class="header-anchor" href="#插件如何订阅事件" aria-label="Permalink to &quot;插件如何订阅事件&quot;">​</a></h2><p>在 <code>meta.yaml</code> 的 <code>events</code> 字段列出要接收的事件类型：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">events</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">message.group</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 群消息（@机器人）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">message.private</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 私聊消息</span></span></code></pre></div><ul><li>只写你需要的类型，不写的不会收到（减少不必要的处理）。</li><li>仅作为拦截器的插件，<code>events</code> 留空 <code>[]</code>，不接收任何入站事件。</li><li>订阅 <code>message.group</code> 和 <code>message.group_full</code> 两个，就能同时收到 @消息和全量消息。</li></ul><h2 id="命名规则" tabindex="-1">命名规则 <a class="header-anchor" href="#命名规则" aria-label="Permalink to &quot;命名规则&quot;">​</a></h2><ul><li>类别前缀：<code>message</code>（消息）、<code>bot</code>（机器人状态）、<code>interaction</code>（交互）、<code>reaction</code>（表态）、<code>audit</code>（审核）。</li><li><code>meta.yaml</code> 的 <code>events</code> <strong>必须用通用类型</strong>，不能用平台原始事件名。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>看消息如何流转到插件 → <a href="./message-flow">消息流转</a></li><li>动手处理事件 → <a href="./../plugin-dev/events">处理事件</a></li></ul>`,24)])])}const g=d(c,[["render",r]]);export{u as __pageData,g as default};
